import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    cache = {}
    last_access = {}

    def memoized_function(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            if timer() - last_access[key] > ttl:
                del cache[key]
                del last_access[key]
            else:
                return cache[key]
        result = cache[key] = memoized_function(*args, **kwargs)
        last_access[key] = timer()
        if len(cache) > maxsize:
            oldest_key = min(last_access, key=last_access.get)
            del cache[oldest_key]
            del last_access[oldest_key]
        return result

    return memoized_function

from collections import OrderedDict

def lfu_cache(maxsize=128, typed=False):
    cache = OrderedDict()
    hits = 0
    misses = 0

    def wrapper(*args, **kwargs):
        nonlocal hits, misses
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            cache.move_to_end(key)
            hits += 1
            return cache[key]
        else:
            misses += 1
            if len(cache) >= maxsize:
                cache.popitem(last=False)
            cache[key] = args, frozenset(kwargs.items())
            return args, frozenset(kwargs.items())

    return wrapper

