def _legacy_mergeOrderings(orderings):
    if not all(isinstance(ordering, list) for ordering in orderings):
        raise ValueError("All orderings must be lists")

    merged_ordering = []
    seen_objects = set()

    for ordering in orderings:
        for obj in ordering:
            if obj in seen_objects:
                merged_ordering.extend(ordering[ordering.index(obj):])
            else:
                seen_objects.add(obj)
                merged_ordering.append(obj)

    return merged_ordering

