def pretty(self, indent=0, debug=False):
    if not isinstance(self, (list, dict)):
        raise TypeError("Input must be a list or dictionary")
    if debug:
        print(f"Pretty printing with indent {indent}")
    if isinstance(self, list):
        return self.__pretty_list(indent)
    elif isinstance(self, dict):
        return self.__pretty_dict(indent)
    else:
        raise TypeError("Unsupported type for pretty printing")

def __pretty_list(self, indent):
    result = "[\n"
    for item in self:
        result += " " * (indent + 4) + self.__pretty(item, indent + 4) + ",\n"
    result += " " * indent + "]"
    return result

def __pretty_dict(self, indent):
    result = "{\n"
    for key, value in self.items():
        result += " " * (indent + 4) + f"'{key}': {self.__pretty(value, indent + 4)},\n"
    result += " " * indent + "}"
    return result

def absorb(self, args):
    result = []
    for arg in args:
        if isinstance(arg, tuple):
            a, b = arg
            if a == b:
                result.append(a)
            elif a == ~b:
                result.append(a & b)
            elif b == ~a:
                result.append(a | b)
        else:
            result.append(arg)
    return result

