import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    try:
        if cwd is None:
            cwd = os.getcwd()
        if env is None:
            env = os.environ.copy()

        if verbose:
            print(f"Running command: {commands} with args: {args} in cwd: {cwd}")

        process = subprocess.Popen(
            [commands] + args,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
            text=True
        )

        stdout, stderr = process.communicate()

        if verbose:
            print(f"Command output: {stdout}")
            if stderr:
                print(f"Command error: {stderr}")

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, f"Command failed with return code {process.returncode}")

        return stdout, stderr
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

