def next_version(version):
    if not isinstance(version, str):
        raise ValueError("Version must be a string")
    if not version:
        raise ValueError("Version string cannot be empty")
    if not version[0].isdigit():
        raise ValueError("Version must start with a digit")
    if version[0] == '0' and version[1:].isdigit():
        raise ValueError("Version cannot start with '0' followed by digits")
    if version.count('.') != 1:
        raise ValueError("Version must contain exactly one dot")
    parts = version.split('.')
    major, minor = int(parts[0]), int(parts[1])
    if major == 0 and minor == 0:
        return '1.0'
    elif major == 0:
        return f'{major}.{minor + 1}'
    elif minor == 0:
        return f'{major + 1}.0'
    else:
        return f'{major}.{minor + 1}'

