def vertex3tuple(vertices):
    if not isinstance(vertices, list) or not all(isinstance(v, tuple) for v in vertices):
        raise ValueError("Input must be a list of tuples representing vertices")

    result = []
    for vertex in vertices:
        if len(vertex) != 2:
            raise ValueError("Each vertex must be a tuple of 2 coordinates")

        # Calculate the points on both sides of the vertex
        point1 = (vertex[0] - 1, vertex[1])
        point2 = (vertex[0] + 1, vertex[1])

        # Append the vertex and the two points to the result list
        result.append((vertex, point1, point2))

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if number < 0:
        raise ValueError("Number must be non-negative")
    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative")

    result = ""
    while number > 0:
        remainder = number % len(alphabet)
        result = alphabet[remainder] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.zfill(padding)

    return result

