            control_args[arg] = arg[7:]
        elif arg.startswith('nested_'):
            nested_args[arg] = arg[7:]
        else:
            raise ValueError(f"Invalid argument: {arg}")

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is not None and not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list")
    if vars_dict is None:
        vars_dict = {}
    if extra_vars is not None:
        vars_dict.update(extra_vars)
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Check if parser_name is valid
    if parser_name not in self.parser_map:
        raise ValueError(f"Invalid parser name: {parser_name}")

    # Get the parser for the given parser_name
    parser = self.parser_map[parser_name]

    # Iterate over the values_dict and convert them to the appropriate types
    for key, value in values_dict.items():
        if key in parser.types:
            try:
                values_dict[key] = parser.types[key](value)
            except ValueError as e:
                raise ValueError(f"Failed to convert {key} to {parser.types[key]}: {e}")

    return values_dict

import os

import json

def get_plugin_spec_flatten_dict(plugin_dir):
    if not os.path.exists(plugin_dir):
        raise FileNotFoundError(f"Plugin directory {plugin_dir} does not exist")

    plugin_spec = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    data = json.load(f)
                    plugin_spec.update(data)

    return plugin_spec

def strip_root(path, root):
    if not path or not root:
        raise ValueError("Both path and root must be provided.")
    if not path.startswith(root):
        raise ValueError("Path does not start with the root.")
    return path[len(root):]
